fn frame(t: i32) {
    host::display::clear(0x101010);
    host::display::draw_string(8, 6, "N", 0x808080, 1);
    host::display::draw_string(60, 6, "N FACT", 0x808080, 1);
    let mut acc: i32 = 1;
    let mut n: i32 = 1;
    while n <= 7 {
        acc = acc * n;
        host::display::draw_number(8, 10 + n * 16, n, 0xffffff, 1);
        host::display::draw_number(60, 10 + n * 16, acc, 0x00ff00, 1);
        n = n + 1;
    }
    host::display::present();
}
